package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

type AuditEntry struct {
	Timestamp time.Time `json:"timestamp"`
	User      string    `json:"user"`
	Action    string    `json:"action"`
	Resource  string    `json:"resource"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// handleSearch processes document search queries
func handleSearch(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("cat")
	owner := r.URL.Query().Get("owner")

	// Build search query with filters
	var conditions []string
	baseQuery := "SELECT id, title, content, owner, created_at FROM documents WHERE 1=1"

	if query != "" {
		// Using to_tsquery for full-text search
		baseQuery += fmt.Sprintf(" AND tsv @@ to_tsquery('english', '%s')", query)
	}
	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = '%s'", category)
	}
	if owner != "" {
		conditions = append(conditions, fmt.Sprintf("owner = '%s'", owner))
	}

	for _, c := range conditions {
		baseQuery += " AND " + c
	}

	baseQuery += " ORDER BY created_at DESC LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v | SQL: %s", err, baseQuery)
		http.Error(w, fmt.Sprintf("Search failed: %v", err), 500)
		return
	}
	defer rows.Close()

	type Document struct {
		ID        int       `json:"id"`
		Title     string    `json:"title"`
		Content   string    `json:"content"`
		Owner     string    `json:"owner"`
		CreatedAt time.Time `json:"created_at"`
	}

	var results []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.Owner, &d.CreatedAt); err != nil {
			continue
		}
		results = append(results, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// handleAuditLog returns recent audit entries
func handleAuditLog(w http.ResponseWriter, r *http.Request) {
	days := r.URL.Query().Get("days")
	if days == "" {
		days = "7"
	}
	// This endpoint uses parameterized query (safe)
	rows, err := db.Query("SELECT timestamp, username, action, resource FROM audit_log WHERE timestamp > NOW() - $1::interval", days+" days")
	if err != nil {
		http.Error(w, "Failed to fetch audit log", 500)
		return
	}
	defer rows.Close()

	var entries []AuditEntry
	for rows.Next() {
		var e AuditEntry
		if err := rows.Scan(&e.Timestamp, &e.User, &e.Action, &e.Resource); err != nil {
			continue
		}
		entries = append(entries, e)
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(entries)
}

// handleHealthCheck for LB health probes
func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s %v", r.RemoteAddr, r.Method, r.URL.Path, time.Since(start))
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/search", handleSearch)
	mux.HandleFunc("/api/audit", handleAuditLog)
	mux.HandleFunc("/health", handleHealthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := &http.Server{
		Addr:         ":" + port,
		Handler:      loggingMiddleware(mux),
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 30 * time.Second,
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(server.ListenAndServe())
}

